const jobs = $('Receive Jobs').all()
  .map(item => item.json || {})
  .filter(job => job.job_id || job.url);


// Normaliza campos que podem aceitar múltiplas opções
function normalizeMulti(value, allowedValues) {
  if (!value) return '';

  const values = Array.isArray(value)
    ? value
    : String(value).split(',');

  const normalized = values
    .map(v => String(v).trim())
    .filter(Boolean)
    .filter(v => allowedValues.includes(v));

  return [...new Set(normalized)].join(', ');
}


// Normaliza campos de seleção única
function normalizeSingle(value, allowedValues) {
  if (!value) return '';

  const normalized = String(value).trim();

  return allowedValues.includes(normalized)
    ? normalized
    : '';
}


return jobs.map(job => {

  /*
    Compatibilidade temporária com o workflow antigo:

    Hoje o Job Scraper ainda pode mandar:
    location = Remote / Hybrid / On-site

    No schema novo isso pertence a work_mode.

    Quando atualizarmos o Job Scraper,
    location passará a representar localização geográfica.
  */
  const legacyLocation = String(job.location || '').trim();

  const workMode =
    normalizeSingle(
      job.work_mode || legacyLocation,
      ['Remote', 'Hybrid', 'On-site']
    );

  const geographicLocation =
    ['Remote', 'Hybrid', 'On-site'].includes(legacyLocation)
      ? ''
      : legacyLocation;


  // Compatibilidade: Pleno antigo -> Mid
  let experience = job.experience || '';

  if (experience === 'Pleno') {
    experience = 'Mid';
  }


  const payment = normalizeMulti(
    job.payment || job.payment_type,
    [
      'Hourly',
      'Fixed-price',
      'Weekly',
      'Monthly',
      'Annual',
      'Not specified'
    ]
  );


  const timeType = normalizeSingle(
    job.time_type,
    [
      'Part-time',
      'Full-time'
    ]
  );


  const jobType = normalizeMulti(
    job.job_type,
    [
      'Contract',
      'Internship',
      'Freelance',
      'Temporary',
      'PJ',
      'CLT',
      'Long-term'
    ]
  );


  const status = normalizeSingle(
    job.status,
    [
      'To do',
      'Applying',
      'Applied',
      'Closed',
      'Mismatch',
      'Not selected',
      'Selected',
      'Interview',
      'Offer',
      'Hired'
    ]
  ) || 'To do';


  return {
    json: {

      // A
      job_id: String(
        job.job_id ||
        `url:${job.url}`
      ),

      // B
      status,

      // C
      date_scraped:
        job.date_scraped || '',

      // D
      source:
        job.source ||
        job._source ||
        '',

      // E
      search_keyword:
        job.search_keyword || '',

      // F
      date_posted:
        job.date_posted || '',

      // G
      title:
        job.title || 'Not specified',

      // H
      work_mode:
        workMode,

      // I
      url:
        job.url || '',

      // J
      company_name:
        job.company_name || '',

      // K
      location:
        job.location_geo ||
        job.job_location ||
        geographicLocation ||
        '',

      // L
      description:
        job.description || '',

      // M
      language:
        normalizeSingle(
          job.language,
          [
            'English',
            'Portuguese'
          ]
        ),

      // N
      payment,

      // O
      time_type:
        timeType,

      // P
      job_type:
        jobType,

      // Q
      experience:
        normalizeSingle(
          experience,
          [
            'Senior',
            'Mid',
            'Specialist',
            'Junior',
            'Intern',
            'Lead'
          ]
        ),

      // R
      salary:
        job.salary || '',

      // S
      match:
        normalizeSingle(
          job.match,
          [
            'Low',
            'Medium',
            'High'
          ]
        ),

      // T
      qualified:
        job.qualified || '',

      // U
      cover_letter:
        job.cover_letter || '',

      // V
      notes:
        job.notes || '',

      // W
      interview_at:
        job.interview_at || '',

      // X
      invite_meet:
        job.invite_meet || '',

      // Y
      attended:
        job.attended === true ||
        job.attended === 'true' ||
        job.attended === 'TRUE',

      // Campos internos que ainda podem ser úteis
      posted_at:
        job.posted_at || '',

      scraped_at:
        job.scraped_at || ''
    }
  };
});

const j = $json;

const months = $('Config').first().json.monthly_sheets;


// Descobre o mês a partir de um timestamp válido
function monthNameFromDate(dateValue) {
  const d = new Date(dateValue);

  if (Number.isNaN(d.getTime())) {
    return null;
  }

  const monthNumber = Number(
    new Intl.DateTimeFormat('en-US', {
      timeZone: $('Config').first().json.timezone,
      month: '2-digit'
    }).format(d)
  );

  return months[monthNumber - 1] || null;
}


// Fallback para Date Scraped em formato brasileiro
function monthNameFromScraped(value) {
  const text = String(value || '').trim();

  const match = text.match(
    /^(\d{2})\/(\d{2})\/(\d{4})(?:\s+\d{2}:\d{2}(?::\d{2})?)?$/
  );

  if (!match) {
    return null;
  }

  const monthNumber = Number(match[2]);

  return months[monthNumber - 1] || null;
}


/*
  Regra de roteamento:

  1. Se posted_at existir, salva na aba referente
     ao mês em que a vaga foi publicada.

  2. Se posted_at não existir, usa Date Scraped.
*/
const targetSheet =
  (j.posted_at
    ? monthNameFromDate(j.posted_at)
    : null) ||
  monthNameFromScraped(j.date_scraped);


if (!targetSheet) {
  throw new Error(
    `Não foi possível identificar a aba mensal. ` +
    `posted_at=${j.posted_at || 'vazio'}; ` +
    `date_scraped=${j.date_scraped || 'vazio'}`
  );
}


if (!months.includes(targetSheet)) {
  throw new Error(
    `Aba mensal inválida: ${targetSheet}`
  );
}


/*
  O Job ID continua na coluna A.

  Portanto o dedupe continua verificando
  a coluna A de todas as 12 abas.
*/
const dedupeRanges = months.map(
  month => `${month}!A:A`
);


const rangesQuery = dedupeRanges
  .map(
    range =>
      `ranges=${encodeURIComponent(range)}`
  )
  .join('&');


return [{
  json: {
    ...j,

    target_sheet: targetSheet,


    /*
      Uma única chamada batchGet procura o Job ID
      nas 12 abas mensais.
    */
    dedupe_url:
      `https://sheets.googleapis.com/v4/spreadsheets/` +
      `${$('Config').first().json.spreadsheet_id}/values:batchGet?` +
      rangesQuery,


    /*
      Nova estrutura da planilha:
      A até Y = 25 colunas.
    */
    append_range_encoded:
      encodeURIComponent(
        `${targetSheet}!A:Y`
      ),


    /*
      Ordem EXATA da nova planilha.
    */
    row_values: [

      j.job_id,          // A  Job ID

      j.status,          // B  Status

      j.date_scraped,    // C  Date Scraped

      j.source,          // D  Source

      j.search_keyword,  // E  Search Keyword

      j.date_posted,     // F  Date Posted

      j.title,           // G  Title

      j.work_mode,       // H  Work Mode

      j.url,             // I  URL

      j.company_name,    // J  Company Name

      j.location,        // K  Location

      j.description,     // L  Description

      j.language,        // M  Language

      j.payment,         // N  Payment

      j.time_type,       // O  Time Type

      j.job_type,        // P  Job Type

      j.experience,      // Q  Experience

      j.salary,          // R  Salary

      j.match,           // S  Match

      j.qualified,       // T  Qualified

      j.cover_letter,    // U  Cover Letter

      j.notes,           // V  Notes

      j.interview_at,    // W  Interview At

      j.invite_meet,     // X  Invite Meet

      j.attended         // Y  Attended
    ]
  }
}];

const ctx = $('Prepare Monthly Row').item.json;

const months = $('Config').first().json.monthly_sheets;

const valueRanges = Array.isArray($json.valueRanges)
  ? $json.valueRanges
  : [];

const existingIds = new Set();
const nextRowsBySheet = {};

function normalizedRangeName(range) {
  return String(range?.range || '')
    .replace(/'/g, '')
    .toUpperCase();
}

for (const range of valueRanges) {
  const values = Array.isArray(range.values)
    ? range.values
    : [];

  for (const row of values) {
    const value = String(row?.[0] ?? '').trim();

    if (value && value !== 'Job ID') {
      existingIds.add(value);
    }
  }
}

/*
  Calcula a próxima linha de todas as abas.
  A aba definitiva será escolhida depois da leitura
  da página pública, quando a data real estiver disponível.
*/
for (const month of months) {
  const range = valueRanges.find(item =>
    normalizedRangeName(item)
      .startsWith(String(month).toUpperCase() + '!A')
  );

  const values = Array.isArray(range?.values)
    ? range.values
    : [];

  let lastUsedRow = 0;

  for (let index = 0; index < values.length; index++) {
    const value = String(
      values[index]?.[0] ?? ''
    ).trim();

    if (value) {
      lastUsedRow = index + 1;
    }
  }

  nextRowsBySheet[month] =
    Math.max(lastUsedRow + 1, 2);
}

const currentId = String(
  ctx.job_id || ''
).trim();

const targetSheetName = String(ctx.target_sheet || '').trim();

const nextRow =
  nextRowsBySheet[targetSheetName] || 2;

const writeRange =
  `${ctx.target_sheet}!A${nextRow}:Y${nextRow}`;

return [{
  json: {
    ...ctx,

    is_new:
      currentId !== '' &&
      !existingIds.has(currentId),

    duplicate_checked_across_12_months: true,

    next_rows_by_sheet:
      nextRowsBySheet,

    next_row:
      nextRow,

    write_range:
      writeRange,

    write_range_encoded:
      encodeURIComponent(writeRange)
  }
}];

return [{
  json: {
    job_id: $json.job_id,
    target_sheet: $json.target_sheet,
    saved: false,
    reason: 'duplicate_job_id'
  }
}];

const original = $('Is New Job?').item.json;

const response = $json || {};

const html =
  typeof response.data === 'string'
    ? response.data
    : typeof response.body === 'string'
      ? response.body
      : '';


// --------------------------------------------------
// HELPERS
// --------------------------------------------------

function decodeHtml(text = '') {
  return String(text)
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/p>/gi, '\n')
    .replace(/<li[^>]*>/gi, '• ')
    .replace(/<\/li>/gi, '\n')
    .replace(/<[^>]+>/g, '')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;/gi, "'")
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&#(\d+);/g, (_, n) =>
      String.fromCharCode(Number(n))
    )
    .replace(/\r/g, '')
    .replace(/[ \t]+\n/g, '\n')
    .replace(/\n[ \t]+/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .replace(/[ \t]{2,}/g, ' ')
    .trim();
}


// --------------------------------------------------
// DESCRIPTION
// --------------------------------------------------

function extractDescription(html) {
  const match = html.match(
    /<div[^>]*class="[^"]*show-more-less-html__markup[^"]*"[^>]*>([\s\S]*?)<\/div>/i
  );

  return match
    ? decodeHtml(match[1])
    : '';
}


// --------------------------------------------------
// LINKEDIN CRITERIA
// --------------------------------------------------

function extractCriteria(html) {
  const criteria = {};

  const regex =
    /<li[^>]*class="[^"]*description__job-criteria-item[^"]*"[^>]*>([\s\S]*?)<\/li>/gi;

  let match;

  while ((match = regex.exec(html)) !== null) {
    const block = match[1];

    const headerMatch = block.match(
      /<h3[^>]*class="[^"]*description__job-criteria-subheader[^"]*"[^>]*>([\s\S]*?)<\/h3>/i
    );

    const valueMatch = block.match(
      /<span[^>]*class="[^"]*description__job-criteria-text[^"]*"[^>]*>([\s\S]*?)<\/span>/i
    );

    if (!headerMatch || !valueMatch) {
      continue;
    }

    const key = decodeHtml(headerMatch[1]);
    const value = decodeHtml(valueMatch[1]);

    if (key && value) {
      criteria[key] = value;
    }
  }

  return criteria;
}


// --------------------------------------------------
// TARGET JOB HTML ONLY
// --------------------------------------------------

/*
  Isola apenas a área correspondente à vaga principal.

  Isso evita capturar Remote, Hybrid etc.
  de vagas recomendadas no final da página.
*/

function extractTargetJobHtml(html) {
  const raw = String(html || '');

  const cutoffMarkers = [
    'find-a-referral',
    'people-also-viewed',
    'base-aside-card',
    'similar-jobs',
  ];

  let cutoff = raw.length;

  for (const marker of cutoffMarkers) {
    const index = raw.indexOf(marker);

    if (index !== -1 && index < cutoff) {
      cutoff = index;
    }
  }

  return raw.slice(0, cutoff);
}


// --------------------------------------------------
// DATE POSTED
// --------------------------------------------------

function formatBrazilDateTime(value) {
  const date =
    value instanceof Date
      ? value
      : new Date(value);

  if (Number.isNaN(date.getTime())) {
    return '';
  }

  const parts =
    new Intl.DateTimeFormat(
      'en-US',
      {
        timeZone: $('Config').first().json.timezone,
        day: '2-digit',
        month: '2-digit',
        year: 'numeric',
        hour: '2-digit',
        minute: '2-digit',
        hour12: false
      }
    )
      .formatToParts(date)
      .reduce((result, part) => {
        result[part.type] = part.value;
        return result;
      }, {});

  return (
    parts.day + '/' +
    parts.month + '/' +
    parts.year + ' ' +
    parts.hour + ':' +
    parts.minute
  );
}

function parsePublishedCandidate(candidate) {
  const value = decodeHtml(candidate)
    .trim();

  if (!value) {
    return null;
  }

  const dateOnlyMatch =
    value.match(/^(\d{4})-(\d{2})-(\d{2})$/);

  if (dateOnlyMatch) {
    return {
      datePosted:
        dateOnlyMatch[3] + '/' +
        dateOnlyMatch[2] + '/' +
        dateOnlyMatch[1],
      postedAt: value,
      precision: 'date'
    };
  }

  if (/^\d{10,13}$/.test(value)) {
    const numeric = Number(value);
    const milliseconds =
      value.length === 10
        ? numeric * 1000
        : numeric;
    const date = new Date(milliseconds);

    if (!Number.isNaN(date.getTime())) {
      return {
        datePosted:
          formatBrazilDateTime(date),
        postedAt:
          date.toISOString(),
        precision: 'datetime'
      };
    }
  }

  const date = new Date(value);

  if (!Number.isNaN(date.getTime())) {
    return {
      datePosted:
        formatBrazilDateTime(date),
      postedAt:
        date.toISOString(),
      precision: 'datetime'
    };
  }

  return null;
}

function extractPublishedInfo(targetHtml, originalJob) {
  const scopedHtml =
    String(targetHtml || '');

  /*
    A página pública tem prioridade porque pode fornecer
    data e horário exatos. O assunto do alerta fica como
    fallback confiável de data quando o HTML não informa
    horário ou está temporariamente indisponível.
  */
  const structuredCandidates = [
    scopedHtml.match(
      /"datePosted"\s*:\s*"([^"]+)"/i
    )?.[1],
    scopedHtml.match(
      /"postedAt"\s*:\s*"([^"]+)"/i
    )?.[1],
    scopedHtml.match(
      /"originallyPostedAt"\s*:\s*"([^"]+)"/i
    )?.[1],
    scopedHtml.match(
      /"listedAt"\s*:\s*"?([0-9]{10,13})"?/i
    )?.[1]
  ].filter(Boolean);

  for (const candidate of structuredCandidates) {
    const parsed =
      parsePublishedCandidate(candidate);

    if (parsed) {
      return {
        ...parsed,
        source: 'public_html_structured'
      };
    }
  }

  const timeTags =
    scopedHtml.match(/<time\b[^>]*>/gi) || [];

  const preferredTimeTag =
    timeTags.find(tag =>
      /main-job-card__listdate/i.test(tag)
    ) ||
    timeTags.find(tag =>
      /\bdatetime\s*=/i.test(tag)
    );

  const datetimeValue =
    preferredTimeTag?.match(
      /\bdatetime\s*=\s*["']([^"']+)["']/i
    )?.[1] || '';

  const parsedTime =
    parsePublishedCandidate(datetimeValue);

  if (parsedTime) {
    return {
      ...parsedTime,
      source: 'public_html_time'
    };
  }

  const originalDatePosted =
    String(originalJob.date_posted || '')
      .trim();

  const originalPostedAt =
    String(originalJob.posted_at || '')
      .trim();

  if (originalDatePosted || originalPostedAt) {
    const parsedOriginal =
      parsePublishedCandidate(
        originalPostedAt
      );

    return {
      datePosted:
        originalDatePosted ||
        parsedOriginal?.datePosted ||
        '',
      postedAt:
        originalPostedAt ||
        parsedOriginal?.postedAt ||
        '',
      precision:
        parsedOriginal?.precision ||
        (originalDatePosted ? 'incoming' : ''),
      source: 'incoming'
    };
  }

  return {
    datePosted: '',
    postedAt: '',
    precision: '',
    source: ''
  };
}


// --------------------------------------------------
// LANGUAGE
// --------------------------------------------------

function detectLanguage(text) {
  const value = String(text || '')
    .toLowerCase()
    .trim();

  if (!value) {
    return '';
  }

  const portugueseMarkers = [
    'experiência',
    'responsabilidades',
    'requisitos',
    'conhecimento',
    'conhecimentos',
    'desenvolvimento',
    'trabalho',
    'buscamos',
    'empresa',
    'equipe',
    'pessoa',
    'pessoas',
    'vaga',
    'tecnologia',
    'engenharia',
    'dados',
    'soluções',
    'projetos',
    'oportunidade',
    'inglês',
    'habilidades',
    'qualificações',
    'atividades',
    'benefícios',
    'profissional',
    'contribuir',
    'liderança',
    'ambiente',
  ];

  const englishMarkers = [
    'experience',
    'responsibilities',
    'requirements',
    'knowledge',
    'development',
    'work',
    'looking for',
    'company',
    'team',
    'candidate',
    'technology',
    'engineering',
    'data',
    'solutions',
    'projects',
    'opportunity',
    'english',
    'skills',
    'qualifications',
    'benefits',
    'professional',
    'leadership',
    'environment',
    'you will',
    'we are',
  ];

  let portugueseScore = 0;
  let englishScore = 0;

  for (const marker of portugueseMarkers) {
    if (value.includes(marker)) {
      portugueseScore++;
    }
  }

  for (const marker of englishMarkers) {
    if (value.includes(marker)) {
      englishScore++;
    }
  }

  if (
    portugueseScore > englishScore &&
    portugueseScore >= 2
  ) {
    return 'Portuguese';
  }

  if (
    englishScore > portugueseScore &&
    englishScore >= 2
  ) {
    return 'English';
  }

  return '';
}


// --------------------------------------------------
// TIME TYPE
// --------------------------------------------------

function detectTimeType(value) {
  const text = String(value || '')
    .toLowerCase();

  if (
    text.includes('tempo integral') ||
    text.includes('full-time') ||
    text.includes('full time')
  ) {
    return 'Full-time';
  }

  if (
    text.includes('meio período') ||
    text.includes('meio periodo') ||
    text.includes('part-time') ||
    text.includes('part time')
  ) {
    return 'Part-time';
  }

  return '';
}


// --------------------------------------------------
// JOB TYPE
// --------------------------------------------------

function detectJobType(employmentRaw, description) {
  const text = `${employmentRaw || ''}\n${description || ''}`
    .toLowerCase();

  const types = [];

  /*
    Só adiciona Job Type quando existe evidência
    explícita no conteúdo da vaga.

    Full-time / Part-time NÃO são Job Type.
    Junior NÃO significa Internship.
  */

  if (/\bclt\b/i.test(text)) {
    types.push('CLT');
  }

  if (
    /\bpj\b/i.test(text) ||
    /\bpessoa jurídica\b/i.test(text) ||
    /\bpessoa juridica\b/i.test(text)
  ) {
    types.push('PJ');
  }

  if (
    /\bfreelance\b/i.test(text) ||
    /\bfreelancer\b/i.test(text)
  ) {
    types.push('Freelance');
  }

  /*
    Internship somente quando há evidência explícita
    de estágio/internship.

    Não usamos Junior, Assistente, "starting career",
    aprendizagem ou mentoria como evidência.
  */
  if (
    /\bestágio\b/i.test(text) ||
    /\bestagio\b/i.test(text) ||
    /\binternship\b/i.test(text)
  ) {
    types.push('Internship');
  }

  if (
    /\btemporário\b/i.test(text) ||
    /\btemporario\b/i.test(text) ||
    /\btemporária\b/i.test(text) ||
    /\btemporaria\b/i.test(text) ||
    /\btemporary\b/i.test(text)
  ) {
    types.push('Temporary');
  }

  if (
    /\blong-term\b/i.test(text) ||
    /\blong term\b/i.test(text) ||
    /\blongo prazo\b/i.test(text)
  ) {
    types.push('Long-term');
  }

  if (
    /\bcontract\b/i.test(text) ||
    /\bcontractor\b/i.test(text) ||
    /\bcontrato\b/i.test(text)
  ) {
    types.push('Contract');
  }

  return [...new Set(types)].join(', ');
}


// --------------------------------------------------
// EXPERIENCE — MULTI-SELECT
// --------------------------------------------------

function detectExperience(value) {
  const text = String(value || '')
    .toLowerCase()
    .trim();

  if (!text) {
    return '';
  }

  /*
    Retorna múltiplos níveis SOMENTE quando a fonte
    descreve explicitamente uma faixa combinada.

    Exemplos:
    Pleno-sênior
    Pleno / Sênior
    Pleno a Sênior
    Mid-Senior
    Mid / Senior
    Mid to Senior

    Senior sozinho continua Senior.
    Mid sozinho continua Mid.
  */

  const explicitMidSeniorRange =
    /\bpleno\s*(?:-|\/|–|—|\ba\b|\be\b)\s*s[eê]nior\b/i.test(text) ||
    /\bmid(?:-level)?\s*(?:-|\/|–|—|\bto\b|\band\b)\s*senior\b/i.test(text);

  if (explicitMidSeniorRange) {
    return 'Mid, Senior';
  }

  if (
    /\btech\s+lead\b/i.test(text) ||
    /\btechnical\s+lead\b/i.test(text) ||
    /\blead\b/i.test(text) ||
    /\blíder\b/i.test(text) ||
    /\blider\b/i.test(text)
  ) {
    return 'Lead';
  }

  /*
    IMPORTANTE:
