  */
  if (
    /\bsr\b\.?/i.test(text) ||
    /\bsênior\b/i.test(text) ||
    /\bsenior\b/i.test(text)
  ) {
    return 'Senior';
  }

  if (
    /\bespecialista\b/i.test(text) ||
    /\bspecialist\b/i.test(text)
  ) {
    return 'Specialist';
  }

  if (
    /\bpleno\b/i.test(text) ||
    /\bmid\b/i.test(text) ||
    /\bmid-level\b/i.test(text) ||
    /\bmid level\b/i.test(text)
  ) {
    return 'Mid';
  }

  /*
    LinkedIn PT-BR pode usar "Assistente"
    para Entry level.
  */
  if (
    /\bassistente\b/i.test(text) ||
    /\bentry level\b/i.test(text) ||
    /\bentry-level\b/i.test(text) ||
    /\bassociate\b/i.test(text)
  ) {
    return 'Junior';
  }

  if (
    /\bjúnior\b/i.test(text) ||
    /\bjunior\b/i.test(text)
  ) {
    return 'Junior';
  }

  if (
    /\bestágio\b/i.test(text) ||
    /\bestagio\b/i.test(text) ||
    /\bintern\b/i.test(text)
  ) {
    return 'Intern';
  }

  return '';
}


