function detectWorkMode(targetHtml, description) {
  const scopedHtml = String(targetHtml || '');
  const descriptionText = String(description || '');

  /*
    Só analisamos o HTML da vaga principal.
    Nunca recomendações.
  */

  const structuredPatterns = [
    /"workplaceType"\s*:\s*"([^"]+)"/i,
    /"workplaceTypes"\s*:\s*\[\s*"([^"]+)"/i,
    /"jobLocationType"\s*:\s*"([^"]+)"/i,
  ];

  for (const pattern of structuredPatterns) {
    const match = scopedHtml.match(pattern);

    if (!match) {
      continue;
    }

    const value = String(match[1] || '')
      .toLowerCase()
      .trim();

    if (
      value.includes('remote') ||
      value.includes('telecommute')
    ) {
      return 'Remote';
    }

    if (value.includes('hybrid')) {
      return 'Hybrid';
    }

    if (
      value.includes('on-site') ||
      value.includes('onsite') ||
      value.includes('on_site')
    ) {
      return 'On-site';
    }
  }


  // --------------------------------------------------
  // LABELS EXPLÍCITOS NO HTML DA VAGA
  // --------------------------------------------------

  const visibleTargetText =
    decodeHtml(scopedHtml)
      .toLowerCase();

  if (
    /\bhybrid\b/i.test(visibleTargetText) ||
    /\bhíbrido\b/i.test(visibleTargetText) ||
    /\bhibrido\b/i.test(visibleTargetText)
  ) {
    return 'Hybrid';
  }

  if (
    /\bon-site\b/i.test(visibleTargetText) ||
    /\bonsite\b/i.test(visibleTargetText) ||
    /\bon site\b/i.test(visibleTargetText) ||
    /\bpresencial\b/i.test(visibleTargetText)
  ) {
    return 'On-site';
  }

  if (
    /\b100%\s*remote\b/i.test(visibleTargetText) ||
    /\bfully remote\b/i.test(visibleTargetText) ||
    /\bremote position\b/i.test(visibleTargetText) ||
    /\bremote role\b/i.test(visibleTargetText) ||
    /\b100%\s*remot[oa]\b/i.test(visibleTargetText) ||
    /\bvaga remot[ae]\b/i.test(visibleTargetText) ||
    /\btrabalho remoto\b/i.test(visibleTargetText)
  ) {
    return 'Remote';
  }


  // --------------------------------------------------
  // DESCRIÇÃO
  // --------------------------------------------------

  if (
    /\b(hybrid|híbrido|hibrido|híbrida|hibrida)\b/i
      .test(descriptionText)
  ) {
    return 'Hybrid';
  }

  if (
    /\b(on-site|onsite|on site|presencial)\b/i
      .test(descriptionText)
  ) {
    return 'On-site';
  }

  if (
    /\b(100%\s*remot[oa]|fully remote|remote position|remote role|vaga remot[ae]|trabalho remoto|trabalhar remotamente)\b/i
      .test(descriptionText)
  ) {
    return 'Remote';
  }

  /*
    Sem evidência real:
    fica vazio.

    Não herdamos Remote do RSS.
  */
  return '';
}


