function calendarKey(year, month, day) {
  const d = new Date(Date.UTC(Number(year), Number(month)-1, Number(day)));
  return d.getUTCFullYear() === Number(year) && d.getUTCMonth()+1 === Number(month) && d.getUTCDate() === Number(day)
    ? Number(String(year).padStart(4,'0') + String(month).padStart(2,'0') + String(day).padStart(2,'0')) : null;
}
function dateKeyFromValue(value) {
  const text = String(value || '')
    .replace(/^'/, '')
    .trim();

  if (!text) {
    return null;
  }

  const isoDate =
    text.match(/^(\d{4})-(\d{2})-(\d{2})(?:$|T)/);

  if (isoDate && !calendarKey(isoDate[1], isoDate[2], isoDate[3])) return null;
  if (isoDate && !text.includes('T')) {
    return Number(
      isoDate[1] + isoDate[2] + isoDate[3]
    );
  }

  const brDate =
    text.match(/^(\d{2})\/(\d{2})\/(\d{4})/);

  if (brDate) {
    return calendarKey(brDate[3], brDate[2], brDate[1]);
  }

  const date = new Date(text);

  if (Number.isNaN(date.getTime())) {
    return null;
  }

  const parts =
    new Intl.DateTimeFormat(
      'en-CA',
      {
        timeZone: $('Config').first().json.timezone,
        year: 'numeric',
        month: '2-digit',
        day: '2-digit'
      }
    )
      .formatToParts(date)
      .reduce((result, part) => {
        result[part.type] = part.value;
        return result;
      }, {});

  return Number(
    parts.year + parts.month + parts.day
  );
}

function isInsideDateScope(key) {
  return (
    Number.isInteger(key) &&
    key >= DATE_SCOPE_START &&
    key <= DATE_SCOPE_END
  );
}

