function extractTechnologies(description) {
  const found = [];

  for (const [name, regex] of techPatterns) {
    if (regex.test(description)) {
      found.push(name);
    }
  }

  return unique(found).slice(0, 20);
}


// -----------------------------------
// FALLBACK SCORING
// -----------------------------------

function requirementScore(value) {
  const text = normalizedMatch(value);

  let score = 0;

  if (
    /\brequire|required|requirement|must have|mandatory|qualification|qualificacao|qualificação|experiencia|experiência|experience\b/.test(text)
  ) {
    score += 5;
  }

  if (
    /\b\d+\+?\s*(?:years?|anos?)\b/.test(text)
  ) {
    score += 4;
  }

  if (
    /\benglish|ingles|inglês|portuguese|portugues|português\b/.test(text)
  ) {
    score += 3;
  }

  if (
    techPatterns.some(([, regex]) =>
      regex.test(value)
    )
  ) {
    score += 2;
  }

  return score;
}

function responsibilityScore(value) {
  const text = normalizedMatch(value);

  let score = 0;

  if (
    /\bdesign|develop|build|implement|lead|manage|mentor|architect|define|create|integrat|automat|deploy|monitor|projetar|desenvolver|construir|implementar|liderar|gerenciar|mentorar|definir|criar\b/.test(text)
  ) {
    score += 4;
  }

  if (
    techPatterns.some(([, regex]) =>
      regex.test(value)
    )
  ) {
    score += 2;
  }

  return score;
}

function topScored(values, scorer, limit) {
  return values
    .map((value, index) => ({
      value,
      index,
      score: scorer(value)
    }))
    .filter(item => item.score > 0)
    .sort((a, b) =>
      b.score - a.score ||
      a.index - b.index
    )
    .slice(0, limit)
    .map(item => item.value);
}


// -----------------------------------
// PARSER
// -----------------------------------

function buildCompactDescription(description) {
  const original = normalize(description);

  if (!original) {
    return '';
  }

  const blocks = original
    .split(/\n{2,}/)
    .map(block => block.trim())
    .filter(Boolean);

  const sections = {
    responsibilities: [],
    requirements: [],
    preferred: [],
    general: []
  };

  let currentSection = null;


  for (const block of blocks) {
    const detected =
      detectSection(block);

    if (detected) {
      currentSection = detected;
      continue;
    }

    if (currentSection === 'ignore') {
      continue;
    }

    // Dentro de uma seção explícita,
    // preservamos o conteúdo do bloco.
    if (
      currentSection === 'responsibilities' ||
      currentSection === 'requirements' ||
      currentSection === 'preferred'
    ) {
      const cleaned = block
        .replace(/^[•●▪◦*-]\s*/, '')
        .trim();

      if (
        cleaned &&
        !isCorporateFluff(cleaned)
      ) {
        sections[currentSection].push(
          cleaned
        );
      }

      continue;
    }


    // Conteúdo fora de seções:
    // usamos apenas se tiver valor técnico.
    if (!isCorporateFluff(block)) {
      sections.general.push(block);
    }
  }


  let responsibilities =
    unique(sections.responsibilities);

  let requirements =
    unique(sections.requirements);

  let preferred =
    unique(sections.preferred);


  // Caso a vaga não tenha headings claros,
  // usa scoring determinístico.
  if (!responsibilities.length) {
    responsibilities =
      topScored(
        sections.general,
        responsibilityScore,
        6
      );
  }

  if (!requirements.length) {
    requirements =
      topScored(
        sections.general,
        requirementScore,
        7
      );
  }


  // Limites de segurança para reduzir tokens.
  responsibilities =
    responsibilities.slice(0, 7);

  requirements =
    requirements.slice(0, 8);

  preferred =
    preferred.slice(0, 5);


  const technologies =
    extractTechnologies(original);


  const output = [];

  if (responsibilities.length) {
    output.push(
      'RESPONSIBILITIES:\n' +
      responsibilities
        .map(value => `• ${value}`)
        .join('\n')
    );
  }

  if (requirements.length) {
    output.push(
      'REQUIREMENTS:\n' +
      requirements
        .map(value => `• ${value}`)
        .join('\n')
    );
  }

  if (technologies.length) {
    output.push(
      'TECH / SKILLS:\n' +
      technologies.join(', ')
    );
  }

  if (preferred.length) {
    output.push(
      'NICE TO HAVE:\n' +
      preferred
        .map(value => `• ${value}`)
        .join('\n')
    );
  }


  // Último fallback.
  if (!output.length) {
    return sections.general
      .slice(0, 8)
      .map(value => `• ${value}`)
      .join('\n');
  }

  return output.join('\n\n');
}


