return jobs.map(item => {
  const job = item.json || {};

  const compactDescription =
    buildCompactDescription(
      job.description || ''
    );


  const updatedJob = {
    ...job,

    description:
      compactDescription ||
      job.description ||
      ''
  };


  // Mantém row_values consistente
  // caso já exista no fluxo.
  if (Array.isArray(job.row_values)) {
    updatedJob.row_values = [
      ...job.row_values
    ];

    // Coluna L = índice 11.
    updatedJob.row_values[11] =
      updatedJob.description;
  }


  return {
    json: updatedJob
  };
});

